<?php
require __DIR__ . '/_bootstrap.php'; global $db;
$uid=api_require_user(); zv2_refresh($uid);

function force_context(int $uid):array{global $db;$h=$db->query("SELECT location,buildings,ressis FROM strongholds WHERE userid=$uid LIMIT 1")->fetch_assoc();$p=explode('|',$h['location']);$levels=pipe_nums($h['buildings']);return[(int)$p[0],(int)$p[1],(int)($levels[10]??0),(int)($levels[4]??0),(int)($levels[3]??0),pipe_nums($h['ressis'])];}
function force_squad(int $uid,int $id):array{foreach(zv2_squads($uid)as$s)if($s['id']===$id)return$s;json_err('bad_squad','Choose one of your squads.');}
function force_equipment_catalog(int $uid):array{global $db;$out=[];$r=$db->query("SELECT i.id,i.name,i.category,i.attack_bonus,i.defense_bonus,v.amount,COALESCE(personal.used,0) personal,COALESCE(squads.used,0) assigned FROM inventory v JOIN items i ON i.id=v.item_id LEFT JOIN (SELECT equipped_weapon item_id,COUNT(*) used FROM survivors WHERE userid=$uid AND equipped_weapon IS NOT NULL GROUP BY equipped_weapon) personal ON personal.item_id=i.id LEFT JOIN (SELECT se.item_id,SUM(se.amount) used FROM squad_equipment se JOIN squads q ON q.id=se.squad_id WHERE q.userid=$uid GROUP BY se.item_id) squads ON squads.item_id=i.id WHERE v.userid=$uid AND (i.attack_bonus>0 OR i.defense_bonus>0) ORDER BY i.category,i.name");while($r&&($i=$r->fetch_assoc()))$out[]=['id'=>(int)$i['id'],'name'=>$i['name'],'category'=>$i['category'],'slot'=>(int)$i['attack_bonus']>0?'weapon':'defense','owned'=>(int)$i['amount'],'personal'=>(int)$i['personal'],'assigned'=>(int)$i['assigned'],'available'=>max(0,(int)$i['amount']-(int)$i['personal']-(int)$i['assigned']),'attackBonus'=>(int)$i['attack_bonus'],'defenseBonus'=>(int)$i['defense_bonus']];return$out;}
function force_vehicle_types():array{global $db;$out=[];$r=$db->query("SELECT * FROM vehicle_types ORDER BY garage_level,id");while($r&&($v=$r->fetch_assoc()))$out[]=['id'=>(int)$v['id'],'name'=>$v['name'],'description'=>$v['description'],'garageLevel'=>(int)$v['garage_level'],'seats'=>(int)$v['seats'],'cargoBonus'=>(int)$v['cargo_bonus'],'speedBonus'=>(int)$v['speed_bonus'],'fuelCapacity'=>(int)$v['fuel_capacity'],'fuelPerTile'=>(int)$v['fuel_per_tile'],'metalCost'=>(int)$v['metal_cost'],'woodCost'=>(int)$v['wood_cost']];return$out;}
function force_vehicles(int $uid):array{global $db;$out=[];$r=$db->query("SELECT v.*,t.name type_name,t.description,t.seats,t.cargo_bonus,t.speed_bonus,t.fuel_capacity,t.fuel_per_tile,t.garage_level FROM vehicles v JOIN vehicle_types t ON t.id=v.type_id WHERE v.userid=$uid ORDER BY v.id");while($r&&($v=$r->fetch_assoc()))$out[]=['id'=>(int)$v['id'],'typeId'=>(int)$v['type_id'],'name'=>$v['name'],'type'=>$v['type_name'],'description'=>$v['description'],'fuel'=>(int)$v['fuel'],'fuelCapacity'=>(int)$v['fuel_capacity'],'fuelPerTile'=>(int)$v['fuel_per_tile'],'seats'=>(int)$v['seats']+(int)$v['seats_upgrade'],'baseSeats'=>(int)$v['seats'],'seatsUpgrade'=>(int)$v['seats_upgrade'],'cargoBonus'=>(int)$v['cargo_bonus']+(int)$v['cargo_upgrade']*10,'baseCargoBonus'=>(int)$v['cargo_bonus'],'cargoUpgrade'=>(int)$v['cargo_upgrade'],'speedBonus'=>(int)$v['speed_bonus'],'garageLevel'=>(int)$v['garage_level'],'assignedSquad'=>$v['assigned_squad']===null?null:(int)$v['assigned_squad']];return$out;}
function force_vehicle(int $uid,int $id):array{foreach(force_vehicles($uid)as$v)if($v['id']===$id)return$v;json_err('bad_vehicle','Choose one of your vehicles.');}
function force_save_resources(int $uid,array $res):void{global $db;$esc=$db->real_escape_string(implode('|',$res));$db->query("UPDATE strongholds SET ressis='$esc' WHERE userid=$uid");}

if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
 $action=(string)($_POST['action']??'');[$hx,$hy,$quarters,$storage,$garage,$resources]=force_context($uid);
 if($action==='create'){
  if($quarters<1)json_err('no_quarters','Build Troop Quarters before forming another squad.');$count=(int)$db->query("SELECT COUNT(*) n FROM squads WHERE userid=$uid")->fetch_assoc()['n'];$limit=min(5,1+$quarters);if($count>=$limit)json_err('squad_limit',"Troop Quarters level $quarters supports $limit squads.");$names=['Alpha','Bravo','Charlie','Delta','Echo'];$name=$names[$count]??('Squad '.($count+1));$db->query("INSERT INTO squads(userid,name,x,y) VALUES($uid,'$name',$hx,$hy)");json_out(['ok'=>true,'message'=>"$name formed. Assign named survivors before deployment."]);
 }
 if($action==='assign'){
  $sid=(int)($_POST['survivor']??0);$qid=(int)($_POST['squad']??0);$sq=force_squad($uid,$qid);if($sq['traveling']||$sq['x']!==$hx||$sq['y']!==$hy)json_err('squad_away','Personnel changes are only possible while the squad is at the stronghold.');$sv=$db->query("SELECT id,name,job_facility FROM survivors WHERE id=$sid AND userid=$uid AND hp>0 LIMIT 1");if(!$sv||!$sv->num_rows)json_err('bad_survivor','Choose an available survivor.');$person=$sv->fetch_assoc();if($person['job_facility']!==null)json_err('survivor_working',$person['name'].' is assigned to a facility.');if($db->query("SELECT survivor_id FROM training_jobs WHERE survivor_id=$sid")->num_rows)json_err('survivor_training',$person['name'].' is currently training.');$vehicle=zv2_squad_vehicle($uid,$qid);if($vehicle&&count($sq['crew'])+1>$vehicle['seats'])json_err('vehicle_seats',$vehicle['name'].' has no free passenger seat. Upgrade it or unassign it first.');$db->begin_transaction();try{$db->query("DELETE FROM squad_members WHERE survivor_id=$sid");$db->query("INSERT INTO squad_members(squad_id,survivor_id) VALUES($qid,$sid)");$db->commit();}catch(Throwable$e){$db->rollback();throw$e;}json_out(['ok'=>true,'message'=>$person['name'].' joined '.$sq['name'].'.']);
 }
 if($action==='remove'){
  $sid=(int)($_POST['survivor']??0);$qid=(int)($_POST['squad']??0);$sq=force_squad($uid,$qid);if($sq['traveling']||$sq['x']!==$hx||$sq['y']!==$hy)json_err('squad_away','The squad must return home before changing personnel.');$db->query("DELETE sm FROM squad_members sm JOIN survivors s ON s.id=sm.survivor_id WHERE sm.squad_id=$qid AND sm.survivor_id=$sid AND s.userid=$uid");json_out(['ok'=>true,'message'=>'Survivor returned to the stronghold reserve.']);
