 if($action==='deposit'){
  $qid=(int)($_POST['squad']??0);$sq=force_squad($uid,$qid);if($sq['traveling']||$sq['x']!==$hx||$sq['y']!==$hy)json_err('squad_away','The squad must be at the stronghold to deposit loot.');if($storage<1)json_err('no_storage','Build a Storage before depositing squad loot.');$cargo=zv2_squad_cargo($qid);if(!$cargo['items'])json_err('no_cargo',$sq['name'].' has no loot to deposit.');$count=array_sum(array_column($cargo['items'],'amount'));$db->begin_transaction();try{foreach($cargo['items']as$item)zv2_add_item($uid,$item['id'],$item['amount']);$db->query("DELETE FROM squad_cargo WHERE squad_id=$qid");$message=$sq['name'].' deposited '.$count.' carried items in Storage.';$escaped=$db->real_escape_string($message);$db->query("INSERT INTO squad_events(squad_id,event_type,message,created_at) VALUES($qid,'deposit','$escaped',".time().")");$db->query("UPDATE squads SET last_event='$escaped' WHERE id=$qid AND userid=$uid");$db->commit();}catch(Throwable$e){$db->rollback();throw$e;}json_out(['ok'=>true,'message'=>$message,'cargo'=>zv2_squad_cargo($qid)]);
 }
 if($action==='equip'||$action==='unequip'){
  $qid=(int)($_POST['squad']??0);$item=(int)($_POST['item']??0);$sq=force_squad($uid,$qid);if($sq['traveling']||$sq['x']!==$hx||$sq['y']!==$hy)json_err('squad_away','Squad equipment can only be changed at the stronghold.');$catalog=force_equipment_catalog($uid);$gear=null;foreach($catalog as$c)if($c['id']===$item)$gear=$c;if(!$gear)json_err('bad_equipment','Choose a weapon or defense item from Storage.');
  if($action==='equip'){if($storage<1)json_err('no_storage','Build Storage before issuing squad equipment.');if(!$sq['crew'])json_err('no_crew','Assign survivors before equipping this squad.');if($gear['available']<1)json_err('equipment_unavailable',$gear['name'].' is already assigned or equipped.');$load=$sq['equipment'];$slots=$load['slots'][$gear['slot']==='weapon'?'weapons':'defense'];if($slots['used']>=$slots['capacity'])json_err('equipment_slots_full','No free '.$gear['slot'].' slots in '.$sq['name'].'.');$db->query("INSERT INTO squad_equipment(squad_id,item_id,amount) VALUES($qid,$item,1) ON DUPLICATE KEY UPDATE amount=amount+1");json_out(['ok'=>true,'message'=>$gear['name'].' equipped by '.$sq['name'].'.']);}
  $owned=$db->query("SELECT amount FROM squad_equipment WHERE squad_id=$qid AND item_id=$item LIMIT 1");if(!$owned||!$owned->num_rows)json_err('not_equipped',$gear['name'].' is not equipped by this squad.');$amount=(int)$owned->fetch_assoc()['amount'];if($amount<=1)$db->query("DELETE FROM squad_equipment WHERE squad_id=$qid AND item_id=$item");else$db->query("UPDATE squad_equipment SET amount=amount-1 WHERE squad_id=$qid AND item_id=$item");json_out(['ok'=>true,'message'=>$gear['name'].' returned to Storage.']);
 }
 if($action==='vehicle_restore'){
  $typeId=(int)($_POST['item']??0);$type=null;foreach(force_vehicle_types()as$t)if($t['id']===$typeId)$type=$t;if(!$type)json_err('bad_vehicle_type','Choose a vehicle design.');if($garage<$type['garageLevel'])json_err('garage_level','Garage level '.$type['garageLevel'].' is required to restore '.$type['name'].'.');if(($resources[3]??0)<$type['metalCost']||($resources[2]??0)<$type['woodCost'])json_err('vehicle_resources','Restoring '.$type['name'].' requires '.$type['metalCost'].' metal and '.$type['woodCost'].' wood.');$resources[3]-=$type['metalCost'];$resources[2]-=$type['woodCost'];$name=$db->real_escape_string($type['name'].' #'.((int)$db->query("SELECT COUNT(*) n FROM vehicles WHERE userid=$uid")->fetch_assoc()['n']+1));$fuel=(int)ceil($type['fuelCapacity']/4);$db->begin_transaction();try{force_save_resources($uid,$resources);$db->query("INSERT INTO vehicles(userid,type_id,name,fuel,created_at) VALUES($uid,$typeId,'$name',$fuel,".time().")");$db->commit();}catch(Throwable$e){$db->rollback();throw$e;}json_out(['ok'=>true,'message'=>$type['name'].' restored in the Garage with '.$fuel.' fuel.']);
