  if($action==='vehicle_assign'){if(!$sq)json_err('bad_squad','Choose a squad.');if($garage<1)json_err('no_garage','Build a Garage before assigning vehicles.');if($sq['traveling']||$sq['x']!==$hx||$sq['y']!==$hy)json_err('squad_away','Vehicles can only be assigned at the stronghold.');if($vehicle['assignedSquad']!==null)json_err('vehicle_assigned',$vehicle['name'].' is already assigned.');if(count($sq['crew'])>$vehicle['seats'])json_err('vehicle_seats',$vehicle['name'].' has '.$vehicle['seats'].' seats for '.count($sq['crew']).' squad members.');$db->query("UPDATE vehicles SET assigned_squad=$qid WHERE id=$vehicleId AND userid=$uid");json_out(['ok'=>true,'message'=>$vehicle['name'].' assigned to '.$sq['name'].'.']);}
  if($action==='vehicle_unassign'){if(!$sq||$vehicle['assignedSquad']!==$qid)json_err('vehicle_squad','That vehicle is not assigned to this squad.');if($sq['traveling']||$sq['x']!==$hx||$sq['y']!==$hy)json_err('squad_away','The squad must return home before releasing its vehicle.');$cargo=$sq['cargo'];$foot=$cargo['footCapacity'];if($cargo['used']>$foot)json_err('vehicle_cargo','Unload cargo until it fits the squad\'s '.$foot.' kg foot capacity.');$db->query("UPDATE vehicles SET assigned_squad=NULL WHERE id=$vehicleId AND userid=$uid");json_out(['ok'=>true,'message'=>$vehicle['name'].' returned to the Garage.']);}
  if($action==='vehicle_refuel'){if($garage<1)json_err('no_garage','Build a Garage before refuelling vehicles.');if($vehicle['assignedSquad']!==null){$vs=force_squad($uid,$vehicle['assignedSquad']);if($vs['traveling']||$vs['x']!==$hx||$vs['y']!==$hy)json_err('vehicle_away','The vehicle must be at the stronghold to refuel.');}$need=max(0,$vehicle['fuelCapacity']-$vehicle['fuel']);if(!$need)json_err('fuel_full',$vehicle['name'].' already has a full tank.');$take=min($need,(int)floor($resources[4]??0));if($take<1)json_err('no_petrol','The stronghold has no petrol for the Garage.');$resources[4]-=$take;$db->begin_transaction();try{force_save_resources($uid,$resources);$db->query("UPDATE vehicles SET fuel=fuel+$take WHERE id=$vehicleId AND userid=$uid");$db->commit();}catch(Throwable$e){$db->rollback();throw$e;}json_out(['ok'=>true,'message'=>$vehicle['name'].' refuelled by '.$take.' units.']);}
  $kind=(string)($_POST['focus']??'');if(!in_array($kind,['seats','cargo'],true))json_err('bad_vehicle_upgrade','Choose a seat or cargo upgrade.');$current=$kind==='seats'?$vehicle['seatsUpgrade']:$vehicle['cargoUpgrade'];$limit=$kind==='seats'?2:3;if($current>=$limit)json_err('vehicle_upgrade_max','That '.$kind.' upgrade is already complete.');$required=$vehicle['garageLevel']+$current;if($garage<$required)json_err('garage_level','Garage level '.$required.' is required for the next '.$kind.' upgrade.');$metal=20+($current+1)*15;$wood=10+($current+1)*5;if(($resources[3]??0)<$metal||($resources[2]??0)<$wood)json_err('vehicle_resources','This upgrade requires '.$metal.' metal and '.$wood.' wood.');if($vehicle['assignedSquad']!==null){$vs=force_squad($uid,$vehicle['assignedSquad']);if($vs['traveling']||$vs['x']!==$hx||$vs['y']!==$hy)json_err('vehicle_away','The vehicle must be at the stronghold for upgrades.');}$resources[3]-=$metal;$resources[2]-=$wood;$field=$kind==='seats'?'seats_upgrade':'cargo_upgrade';$db->begin_transaction();try{force_save_resources($uid,$resources);$db->query("UPDATE vehicles SET $field=$field+1 WHERE id=$vehicleId AND userid=$uid");$db->commit();}catch(Throwable$e){$db->rollback();throw$e;}json_out(['ok'=>true,'message'=>$vehicle['name'].' received a '.$kind.' upgrade.']);
 }
 if($action==='train'){
