[$hx,$hy,$quarters,$storage,$garage,$resources]=force_context($uid);$squads=zv2_squads($uid);$squadNames=[];foreach($squads as$s)$squadNames[$s['id']]=$s['name'];$survivors=[];$q=$db->query("SELECT s.id,s.name,s.hp,s.max_hp,s.attack_stat,s.defense_stat,s.equipped_weapon,s.job_facility,s.fatigue,i.name weapon,sm.squad_id,t.focus,t.due,ht.started_at treatment_started,ht.due treatment_due,ht.soldier_level,ht.hospital_level FROM survivors s LEFT JOIN items i ON i.id=s.equipped_weapon LEFT JOIN squad_members sm ON sm.survivor_id=s.id LEFT JOIN training_jobs t ON t.survivor_id=s.id LEFT JOIN hospital_treatments ht ON ht.survivor_id=s.id WHERE s.userid=$uid ORDER BY s.name");while($q&&($v=$q->fetch_assoc()))$survivors[]=['id'=>(int)$v['id'],'name'=>$v['name'],'hp'=>(int)$v['hp'],'maxHp'=>(int)$v['max_hp'],'attack'=>(int)$v['attack_stat'],'defense'=>(int)$v['defense_stat'],'level'=>zv2_soldier_level($v),'fatigue'=>(int)$v['fatigue'],'weapon'=>$v['weapon'],'squadId'=>$v['squad_id']===null?null:(int)$v['squad_id'],'squad'=>$v['squad_id']===null?null:($squadNames[(int)$v['squad_id']]??null),'job'=>$v['job_facility']===null?null:(int)$v['job_facility'],'training'=>$v['focus']?['focus'=>$v['focus'],'due'=>(int)$v['due']]:null,'treatment'=>$v['treatment_due']===null?null:['startedAt'=>(int)$v['treatment_started'],'due'=>(int)$v['treatment_due'],'soldierLevel'=>(int)$v['soldier_level'],'hospitalLevel'=>(int)$v['hospital_level']]];$rq=$db->query("SELECT COUNT(*) total,SUM(found_at>0) found FROM recruit_encounters WHERE userid=$uid")->fetch_assoc();json_out(['ok'=>true,'quarters'=>['level'=>$quarters,'squadLimit'=>min(5,1+$quarters),'trainingCapacity'=>$quarters?min(3,max(1,(int)ceil($quarters/2))):0],'storage'=>['level'=>$storage,'acceptsLoot'=>$storage>0],'garage'=>['level'=>$garage,'petrol'=>(int)floor($resources[4]??0),'metal'=>(int)floor($resources[3]??0),'wood'=>(int)floor($resources[2]??0)],'home'=>['x'=>$hx,'y'=>$hy],'squads'=>$squads,'survivors'=>$survivors,'equipmentCatalog'=>force_equipment_catalog($uid),'vehicleTypes'=>force_vehicle_types(),'vehicles'=>force_vehicles($uid),'recruits'=>['found'=>(int)$rq['found'],'total'=>(int)$rq['total']]]);
